#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_URL_LEN 2048
#define MAX_DOMAIN_LEN 256
#define AUDIT_LOG "/var/log/cicd/oauth_audit.log"

typedef struct {
    char client_id[64];
    char redirect_uri[MAX_URL_LEN];
    char state[128];
    char scope[256];
} OAuthRequest;

typedef struct {
    char allowed_domains[8][MAX_DOMAIN_LEN];
    int num_domains;
    bool enforce_https;
    bool allow_subdomains;
} OAuthConfig;

static void audit_log(const char *event, const char *detail, bool success) {
    FILE *f = fopen(AUDIT_LOG, "a");
    if (!f) return;
    time_t now = time(NULL);
    char timebuf[64];
    strftime(timebuf, sizeof(timebuf), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
    fprintf(f, "{\"ts\":\"%s\",\"event\":\"%s\",\"detail\":\"%s\",\"ok\":%s}\n",
            timebuf, event, detail, success ? "true" : "false");
    fclose(f);
}

static bool parse_scheme(const char *url, char *scheme, size_t scheme_len) {
    const char *sep = strstr(url, "://");
    if (!sep || (size_t)(sep - url) >= scheme_len) return false;
    memcpy(scheme, url, sep - url);
    scheme[sep - url] = '\0';
    return true;
}

static const char *extract_host(const char *url) {
    const char *after_scheme = strstr(url, "://");
    if (!after_scheme) return NULL;
    return after_scheme + 3;
}

static bool extract_domain(const char *host_start, char *domain, size_t domain_len) {
    if (!host_start) return false;
    const char *end = host_start;
    /* Walk until we hit path separator, query, fragment, or port */
    while (*end && *end != '/' && *end != '?' && *end != '#' && *end != ':') {
        end++;
    }
    size_t len = end - host_start;
    if (len == 0 || len >= domain_len) return false;
    memcpy(domain, host_start, len);
    domain[len] = '\0';
    return true;
}

/* Check if candidate is a subdomain of parent.
 * e.g., "ci.builds.example.com" is subdomain of "example.com" */
static bool is_subdomain_of(const char *candidate, const char *parent) {
    size_t clen = strlen(candidate);
    size_t plen = strlen(parent);
    if (clen <= plen) return false;
    /* candidate must end with parent */
    const char *suffix = candidate + (clen - plen);
    if (strcmp(suffix, parent) != 0) return false;
    /* character before the suffix must be '.' for proper subdomain */
    if (suffix[-1] != '.') return false;
    return true;
}

static bool validate_redirect_uri(const OAuthConfig *config, const char *uri) {
    char scheme[16];
    char domain[MAX_DOMAIN_LEN];

    if (strlen(uri) >= MAX_URL_LEN) {
        audit_log("redirect_validate", "uri_too_long", false);
        return false;
    }

    if (!parse_scheme(uri, scheme, sizeof(scheme))) {
        audit_log("redirect_validate", "bad_scheme_parse", false);
        return false;
    }

    if (config->enforce_https && strcmp(scheme, "https") != 0) {
        audit_log("redirect_validate", "scheme_not_https", false);
        return false;
    }

    const char *host_start = extract_host(uri);
    if (!extract_domain(host_start, domain, sizeof(domain))) {
        audit_log("redirect_validate", "bad_domain_extract", false);
        return false;
    }

    /* Reject if domain contains embedded credentials (user:pass@host) */
    if (strchr(domain, '@') != NULL) {
        audit_log("redirect_validate", "embedded_credentials", false);
        return false;
    }

    for (int i = 0; i < config->num_domains; i++) {
        if (strcmp(domain, config->allowed_domains[i]) == 0) {
            audit_log("redirect_validate", domain, true);
            return true;
        }
        if (config->allow_subdomains && is_subdomain_of(domain, config->allowed_domains[i])) {
            audit_log("redirect_validate", domain, true);
            return true;
        }
    }

    audit_log("redirect_validate", "domain_not_allowed", false);
    return false;
}

static bool process_oauth_callback(const OAuthConfig *config, const OAuthRequest *req) {
    if (!validate_redirect_uri(config, req->redirect_uri)) {
        return false;
    }
    audit_log("oauth_callback", req->client_id, true);
    /* Issue token and redirect... */
    printf("Redirecting to: %s\n", req->redirect_uri);
    return true;
}

int main(int argc, char *argv[]) {
    OAuthConfig config = {
        .allowed_domains = {"ci.internal.corp", "builds.internal.corp"},
        .num_domains = 2,
        .enforce_https = true,
        .allow_subdomains = true
    };

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <client_id> <redirect_uri> [state]\n", argv[0]);
        return 1;
    }

    OAuthRequest req = {0};
    strncpy(req.client_id, argv[1], sizeof(req.client_id) - 1);
    strncpy(req.redirect_uri, argv[2], sizeof(req.redirect_uri) - 1);
    if (argc > 3) strncpy(req.state, argv[3], sizeof(req.state) - 1);
    strncpy(req.scope, "pipeline:read pipeline:write", sizeof(req.scope) - 1);

    if (process_oauth_callback(&config, &req)) {
        printf("OAuth flow completed successfully.\n");
        return 0;
    } else {
        fprintf(stderr, "OAuth redirect validation failed.\n");
        return 1;
    }
}
